\label{canonical_form_W_i(x)}
$W_j(x)$ is an $\mathbb{F}_2$-linearlized polynomial for which
\begin{equation}\label{eq:W_i(x)}
W_j(x)=\sum_{i=0}^{j}a_{j,i}x^{2^i},
\end{equation}
where each $a_{j,i}\in \mathbb{F}_{2^r}$ is a constant. Furthermore,
\begin{equation}\label{linear}
W_j(x+y)=W_j(x)+W_j(y), \forall x,y \in \mathbb{F}_{2^r}.
\end{equation}

\label{polynomial-1}
A form of polynomial expression over $\mathbb{F}_{2^r}$ is defined as
\begin{equation}\label{eq:polyexp}
[D_h](x)=\sum_{i=0}^{h-1}d_iX_i(x),
\end{equation}
where
\begin{equation}\label{eq:polyvec}
D_h=(d_0, d_1,\dots , d_{h-1})
\end{equation}
is an $h$-element vector denoting the polynomial coefficients and $h\le 2^r$. Consequently, $deg([D_h](x))\leq h-1$.

\label{P_j^i(x)}
\begin{equation}\label{eq:Delta_j,H^i(xoplusb)}
\Delta_i^m(x+y)=\Delta_i^m(x),\forall y\in \{\omega_b\}_{b=0}^{2^i-1}.
\end{equation}
\begin{proof}
By Lemma \ref{canonical_form_W_i(x)}, we have
{\small \begin{equation}\label{eq:W_j(xoplus b)}
W_i(x+y)=W_i(x)+ W_i(y)=W_i(x),\forall y\in \{\omega_b\}_{b=0}^{2^i-1}.
\end{equation}}

The proof follows mathematical induction on $i$. In the base case, we consider \eqref{eq:P_j^i(x)rec} at $i=\lg(h)-1$:
\begin{align*}
&\Delta_{\lg(h)-1}^m(x)\\
=&\Delta_{\lg(h)}^m(x)+ \frac{W_{\lg(h)-1}(x)}{W_{\lg(h)-1}(\omega_{2^{\lg(h)-1}})}\Delta_{\lg(h)}^{m+2^{\lg(h)-1}}(x)\\
=&d_m+ \frac{W_{\lg(h)-1}(x)}{W_{\lg(h)-1}(\omega_{2^{\lg(h)-1}})}d_{m+2^{\lg(h)-1}}.
\end{align*}

From \eqref{eq:W_j(xoplus b)}, we have
\begin{align*}
&\Delta_{\lg(h)-1}^m(x+y)\\
=&d_m+ \frac{W_{\lg(h)-1}(x+y)}{W_{\lg(h)-1}(\omega_{2^{\lg(h)-1}})}d_{m+2^{\lg(h)-1}}\\
=&d_m+ \frac{W_{\lg(h)-1}(x)}{W_{\lg(h)-1}(\omega_{2^{\lg(h)-1}})}d_{m+2^{\lg(h)-1}}\\
=&\Delta_{\lg(h)-1}^m(x),\forall y\in \{\omega_b\}_{b=0}^{h/2-1}.
\end{align*}
Thus \eqref{eq:Delta_j,H^i(xoplusb)} holds for $i=\lg(h)-1$.

Assume \eqref{eq:Delta_j,H^i(xoplusb)} holds for $i=c+1$. When $i=c$, we have
\begin{align*}
&\Delta_c^m(x+y)\\
=&\Delta_{c+1}^m(x+y)+ \frac{W_c(x+y)}{W_c(\omega_{2^c})}\Delta_{c+1}^{m+2^c}(x+y)\\
=&\Delta_{c+1}^m(x+y)+ \frac{W_c(x)}{W_c(\omega_{2^c})}\Delta_{c+1}^{m+2^c}(x+y)\\
=&\Delta_{c+1}^m(x)+ \frac{W_c(x)}{W_c(\omega_{2^c})}\Delta_{c+1}^{m+2^c}(x)\\
=&\Delta_c^m(x), \forall y\in \{\omega_b\}_{b=0}^{2^c-1}.&
\end{align*}
This completes the proof.
\end{proof}

\label{W'_j(x)}
The formal derivative of $W_i(x)$ is a constant given by
\begin{equation}
W_i'(x)=\prod_{j=1}^{2^i-1}\omega_j.
\end{equation}
\begin{proof}
Let
\[
C(x)=c\cdot x^j,
\]
where $c\in \mathbb{F}_{2^r}$. Its formal derivative is defined as
\[
C'(x)=\left\{\begin{matrix}
0 & \textrm{if $j$ is even;}\\
cx^{j-1} & \textrm{otherwise.}
\end{matrix}\right.
\]
From Lemma \ref{canonical_form_W_i(x)}, $W_i(x)$ has terms in the degrees of $1,2,4,\dots ,2^i$, so the formal derivative of $W_i(x)$ is a constant that is the coefficient of $W_i(x)$ at degree $1$. The value is
\[
\sum_{l=0}^{2^i-1}\prod_{j\neq l}\omega_j=\prod_{j=1}^{2^i-1}\omega_j.
\]
This completes the proof.
\end{proof}
